import subprocess, json, sys, os
from datetime import datetime

# The target image we scanned
import sys
IMAGE = sys.argv[1] if len(sys.argv) > 1 else "python:3.8-slim"
def main():
    print(f"[*] Reading scan results for: {IMAGE} ...")
    
    # Check if the JSON file exists
    if not os.path.exists("report.json"):
        print("[!] Error: report.json not found. Please run the Grype scan command first.")
        sys.exit(1)

    # Load JSON data generated by Grype
    with open("report.json", "r", encoding="utf-8") as f:
        data = json.load(f)

    matches = data.get("matches", [])
    count = {"Critical": 0, "High": 0, "Medium": 0, "Low": 0, "Negligible": 0}
    important = []
    
    # Analyze and categorize vulnerabilities
    for m in matches:
        sev = m["vulnerability"]["severity"]
        count[sev] = count.get(sev, 0) + 1
        if sev in ("Critical", "High"):
            fixes = m["vulnerability"].get("fix", {}).get("versions") or ["Not Available"]
            important.append({
                "cve": m["vulnerability"]["id"],
                "pkg": m["artifact"]["name"],
                "ver": m["artifact"]["version"],
                "fix": fixes[0],
                "sev": sev,
            })

    # Prepare table rows for the report
    rows = "".join(f"<tr><td>{c}</td><td>{count[c]}</td></tr>" for c in count)
    
    # Show top 20 important vulnerabilities
    vulns = "".join(
    f"""<tr>
    <td>{v['cve']}</td>
    <td>{v['pkg']}</td>
    <td>{v['ver']}</td>
    <td>{v['fix']}</td>
    <td class='sev-{v['sev']}'>{v['sev']}</td>
    <td>
        <button onclick="alert('CVE: {v['cve']}\\nPackage: {v['pkg']}\\nCurrent: {v['ver']}\\nFix: {v['fix']}\\nSeverity: {v['sev']}')">عرض التفاصيل</button>
    </td>
    </tr>""" for v in important[:20]
)
    # HTML Template (Arabic Report for the user/institution)
    html = f"""<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="UTF-8">
<title>تقرير الفحص الأمني</title>
<style>
body{{font-family:'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; padding:30px; background-color:#f4f7f6; color:#333;}}
.container{{max-width:1000px; margin:auto; background:white; padding:20px; border-radius:10px; box-shadow:0 4px 8px rgba(0,0,0,0.1);}}
h1{{color:#2c3e50; text-align:center;}}
table{{border-collapse:collapse; width:100%; margin-top:15px;}}
th,td{{border:1px solid #ddd; padding:12px; text-align:right;}}
th{{background-color:#34495e; color:white;}}
tr:nth-child(even){{background-color:#f9f9f9;}}
.sev-Critical{{color:#e74c3c; font-weight:bold;}}
.sev-High{{color:#e67e22; font-weight:bold;}}
.summary-box{{background-color:#e8f4f8; padding:15px; border-right:5px solid #3498db; margin-bottom:20px;}}
</style></head><body>
<div class="container">
<h1>🛡️ تقرير الفحص الأمني للتطبيقات</h1>
<div class="summary-box">
    <p><b>التطبيق المفحوص:</b> {IMAGE}</p>
    <p><b>تاريخ الفحص:</b> {datetime.now():%Y-%m-%d %H:%M}</p>
    <p><b>إجمالي الثغرات المكتشفة:</b> {len(matches)}</p>
</div>
<h2>📊 ملخص الثغرات حسب الخطورة</h2>
<table><tr><th>مستوى الخطورة</th><th>العدد</th></tr>{rows}</table>

<h2>⚠️ أهم الثغرات (Critical + High)</h2>
<p><i>(يتم عرض أول 20 ثغرة فقط للاختصار)</i></p>
<table><tr><th>رقم الثغرة (CVE)</th><th>المكتبة المصابة</th><th>الإصدار الحالي</th>
<th>الإصدار المصلح</th><th>الخطورة</th><th>التفاصيل</th></tr>{vulns}</table>

<div style="margin-top:30px; text-align:center; color:#7f8c8d; font-size:14px;">
    تم إنشاء هذا التقرير تلقائياً باستخدام أداة Grype - مشروع حماية المؤسسات الصغيرة
</div>
</div>
</body></html>"""
# Save the HTML report
    report_path = os.path.join(
        os.path.dirname(os.path.abspath(__file__)),
        "security_report.html"
    )

    with open(report_path, "w", encoding="utf-8") as f:
        f.write(html)

    print("[+] Report generated successfully: security_report.html")
    print(f"[*] Stats: Critical={count['Critical']} | High={count['High']} | Medium={count['Medium']}")

    # Security Gate
    if count["Critical"] > 0:
        print("[!] WARNING: Critical vulnerabilities found! Stop deployment and fix them.")
        sys.exit(2)

    print("[+] No Critical vulnerabilities found. The application is safe to deploy.")


if __name__ == "__main__":
    main()
    